import { describe, expect, it } from "vitest";

import { deriveActionToken, deriveCallsListName, deriveConditionRaw } from "../../src/simc/apl-authority.js";
import { FORBIDDEN_DERIVED_ACTION_KEYS } from "../../src/simc/authority-artifact.js";
import { pinnedAssassinationAuthority } from "../../src/simc/pinned-authority.js";
import artifact from "../../src/simc/data/rogue-assassination.apl.json";

/**
 * The pinned authority artifact is the whole rotational authority.
 *
 * It was generated by `scripts/authority/extract-simc-apl.mjs` from one exact
 * commit, and the extractor verified the facts below against the LIVE pinned
 * source before writing. This test re-asserts them against the committed file,
 * so a hand-edit, a regeneration from a different commit, or an upstream change
 * that alters the rotation cannot pass silently.
 *
 * If one of these fails after a re-pin, the correct response is to report the
 * discrepancy — not to update the expectation until it matches.
 */

const SPEND_CONDITION = "!buff.darkest_night.up&combo_points>=5|buff.darkest_night.up&combo_points.deficit=0";
const GENERATE_CONDITION =
  "!buff.darkest_night.up&combo_points<5|buff.darkest_night.up&combo_points.deficit>0";

const loaded = pinnedAssassinationAuthority();

function listNamed(name: string) {
  if (!loaded.ok) return undefined;
  return loaded.authority.artifact.lists.find((list) => list.listName === name);
}

describe("provenance identifies exactly one commit", () => {
  it("records a full commit sha, a source hash and the extraction tool", () => {
    if (!loaded.ok) return;
    const { provenance } = loaded.authority.artifact;
    expect(provenance.repository).toBe("https://github.com/simulationcraft/simc");
    expect(provenance.commitSha).toMatch(/^[0-9a-f]{40}$/);
    expect(provenance.commitDate).toMatch(/^\d{4}-\d{2}-\d{2}$/);
    expect(provenance.sourcePath).toBe("engine/class_modules/apl/apl_rogue.cpp");
    expect(provenance.sourceSha256).toMatch(/^[0-9a-f]{64}$/);
    expect(provenance.sourceByteLength).toBeGreaterThan(0);
    expect(provenance.extractedOn).toMatch(/^\d{4}-\d{2}-\d{2}$/);
    expect(provenance.extractorVersion).toBeGreaterThan(0);
  });

  it("names the bounded region the extractor was allowed to read", () => {
    if (!loaded.ok) return;
    const { provenance } = loaded.authority.artifact;
    expect(provenance.regionStartMarker).toBe("//assassination_apl_start");
    expect(provenance.regionEndMarker).toBe("//assassination_apl_end");
  });
});

describe("the required authority facts hold in the pinned commit", () => {
  it("calls cds and core_dot before generate and spend", () => {
    const calls = (listNamed("default")?.actions ?? [])
      .map((action) => deriveCallsListName(action.actionStringVerbatim))
      .filter((name): name is string => name !== null);
    expect(calls).toEqual(["cds", "core_dot", "generate", "spend"]);
  });

  it("carries the exact spend call condition", () => {
    const spendCall = listNamed("default")?.actions.find(
      (action) => deriveCallsListName(action.actionStringVerbatim) === "spend",
    );
    expect(spendCall).toBeDefined();
    expect(deriveConditionRaw(spendCall?.actionStringVerbatim ?? "")).toBe(SPEND_CONDITION);
  });

  it("carries the exact generate call condition", () => {
    const generateCall = listNamed("default")?.actions.find(
      (action) => deriveCallsListName(action.actionStringVerbatim) === "generate",
    );
    expect(deriveConditionRaw(generateCall?.actionStringVerbatim ?? "")).toBe(GENERATE_CONDITION);
  });

  it("holds every Envenom action, and holds them only in spend", () => {
    if (!loaded.ok) return;
    expect(loaded.authority.listsContainingAction("envenom")).toEqual(["spend"]);
    const envenomActions = (listNamed("spend")?.actions ?? []).filter(
      (action) => deriveActionToken(action.actionStringVerbatim) === "envenom",
    );
    expect(envenomActions).toHaveLength(3);
    expect(envenomActions.map((action) => action.actionStringVerbatim)).toEqual([
      "envenom,if=buff.envenom.remains<=1|buff.deathmark.up",
      "envenom,if=energy.pct>70|fight_remains<15",
      "envenom,if=energy.pct>30&(target.time_to_die<12|spell_targets.fan_of_knives>=4)",
    ]);
  });

  it("holds crimson_tempest in the generate list", () => {
    if (!loaded.ok) return;
    // The reason ability identity is required at all: a cast that consumes
    // combo points does NOT identify the spend list.
    expect(loaded.authority.listsContainingAction("crimson_tempest")).toEqual(["generate"]);
  });

  it("proves the sole gate to envenom", () => {
    if (!loaded.ok) return;
    const proof = loaded.authority.proveSoleGateTo("envenom");
    expect(proof.kind).toBe("PROVEN_SOLE_GATE");
    if (proof.kind !== "PROVEN_SOLE_GATE") return;
    expect(proof.gate.fromListName).toBe("default");
    expect(proof.gate.conditionRaw).toBe(SPEND_CONDITION);
  });
});

describe("the artifact is a faithful copy, not a rewrite", () => {
  const raw = artifact as unknown as {
    lists: { listName: string; actions: { actionStringVerbatim: string; sourceLine: number }[] }[];
  };

  it("stores the add_action argument, not a synthesized actions+=/ line", () => {
    // The source is C++ `add_action("...")`. Calling a fabricated
    // `actions+=/...` string "verbatim" would be a false provenance claim.
    for (const list of raw.lists) {
      for (const action of list.actions) {
        expect(action.actionStringVerbatim.startsWith("actions")).toBe(false);
        expect(action.actionStringVerbatim.includes("+=/")).toBe(false);
        expect(action.actionStringVerbatim.length).toBeGreaterThan(0);
      }
    }
  });

  it("stores no derived field, so derivation cannot drift from the source string", () => {
    for (const list of raw.lists) {
      for (const action of list.actions) {
        for (const forbidden of FORBIDDEN_DERIVED_ACTION_KEYS) {
          expect(action).not.toHaveProperty(forbidden);
        }
      }
    }
  });

  it("every derived field is reproducible from the verbatim string", () => {
    if (!loaded.ok) return;
    for (const action of loaded.authority.actions) {
      expect(action.actionToken).toBe(deriveActionToken(action.actionStringVerbatim));
      expect(action.conditionRaw).toBe(deriveConditionRaw(action.actionStringVerbatim));
      expect(action.callsListName).toBe(deriveCallsListName(action.actionStringVerbatim));
    }
  });

  it("keeps a source line for every action", () => {
    for (const list of raw.lists) {
      for (const action of list.actions) {
        expect(action.sourceLine).toBeGreaterThan(0);
      }
    }
  });

  it("contains no credential-shaped value", () => {
    const serialized = JSON.stringify(artifact).toLowerCase();
    for (const forbidden of ["client_secret", "access_token", "authorization", "bearer "]) {
      expect(serialized).not.toContain(forbidden);
    }
  });
});
